	const useCase = new CreateNote(notes, fakeIds("note-1"), fixedClock("2026-01-01T00:00:00Z"));

	const result = await useCase.execute({ title: "Shopping", body: "milk" });

	expect(result.isSuccess()).toBe(true);
	expect(await notes.findById("note-1")).not.toBeNull();
});

