import type { NoteRepository } from "./ports";
import { Title } from "../entities/title";

export class CreateNote {
	constructor(private readonly notes: NoteRepository) {}

	async execute(input: { title: string; body: string }) {
		const title = Title.create(input.title);
		if (title.isFailure()) {
			return { status: 400, body: { error: title.error.message } };
		}
		const note = await this.notes.add(title.value, input.body);
		return { status: 201, body: { id: note.id } };
	}
}

